package com.networkmonitorpro.ui.adapter; import androidx.annotation.NonNull;import androidx.fragment.app.*;import com.networkmonitorpro.ui.*; public class PagerAdapter extends FragmentStateAdapter{ public PagerAdapter(@NonNull FragmentActivity a){super(a);} public int getItemCount(){return 4;} @NonNull public Fragment createFragment(int p){ if(p==1)return new NotifierFragment(); if(p==2)return new DownloaderFragment(); if(p==3)return new SettingsFragment(); return new DashboardFragment();} }
